contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single test function: take an arbitrary payment amount and an address to act as msg.sender for a call
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read before-values
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint contract_balance_before = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint contract_balance_after = address(c).balance;

        // General invariant to assert:
        // - If pot decreased, then it must have become exactly 0.
        // - When pot becomes 0 after the call, the contract's balance decreased by (pot_before) and the bank may have received FEE_AMOUNT (i.e., contract balance after = contract balance before - pot_before)
        //   Note: Because transfers go out to bank and player, the net contract balance reduction equals pot_before when payout happened.
        assert((pot_after <= pot_before ? pot_after == 0 : pot_after == pot_before + (reverted ? 0 : amount))
               && (pot_after == 0 ? contract_balance_after + pot_before == contract_balance_before : true));
    }

    receive() external payable {}
}

